source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Runs of the 5-colored guide lines.
    vertical = []
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == 5:
                r += 1
            if r - start >= 2:
                vertical.append((c, start, r - 1))

    horizontal = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 5:
                c += 1
            if c - start >= 2:
                horizontal.append((r, start, c - 1))

    # A vertical guide repeats the colored horizontal swatch at its end
    # along the length of the guide.
    for c, top, bottom in vertical:
        for side in (1, -1):
            sc = c + side
            if not (0 <= sc < w):
                continue
            for anchor, step in ((bottom, -1), (top, 1)):
                if grid[anchor][sc] == 0 or grid[anchor][sc] == 5:
                    continue
                width = 0
                cc = sc
                while 0 <= cc < w and grid[anchor][cc] not in (0, 5):
                    width += 1
                    cc += side
                rows = [anchor]
                rr = anchor + step
                while top <= rr <= bottom and all(grid[rr][sc + side*k] not in (0, 5) for k in range(width)):
                    rows.append(rr)
                    rr += step
                rows.sort()
                seed = [[grid[rr][sc + side*k] for k in range(width)] for rr in rows]
                seed_top = rows[0]
                for rr in range(top, bottom + 1):
                    patrow = (rr - seed_top) % len(seed)
                    for k in range(width):
                        cc = sc + side*k
                        if 0 <= cc < w and out[rr][cc] != 5:
                            out[rr][cc] = seed[patrow][k]
                break

    # A horizontal guide can likewise repeat a vertical swatch sideways;
    # another 5 guide bounds the filled region.
    for r, left, right in horizontal:
        for source_c, direction in ((left, 1), (right, -1)):
            for anchor, step in ((r + 1, 1), (r - 1, -1)):
                if not (0 <= anchor < h) or grid[anchor][source_c] in (0, 5):
                    continue
                seed_rows = []
                rr = anchor
                while 0 <= rr < h and grid[rr][source_c] not in (0, 5):
                    seed_rows.append(rr)
                    rr += step
                seed_rows.sort()
                seed = [grid[rr][source_c] for rr in seed_rows]
                # Stop at the nearest perpendicular guide line.
                bound = w
                if direction > 0:
                    for cc in range(source_c + 1, w):
                        if any(grid[rr][cc] == 5 for rr in seed_rows):
                            bound = cc
                            break
                    cols = range(source_c, bound)
                else:
                    bound = -1
                    for cc in range(source_c - 1, -1, -1):
                        if any(grid[rr][cc] == 5 for rr in seed_rows):
                            bound = cc
                            break
                    cols = range(source_c, bound, -1)
                for cc in cols:
                    for rr in seed_rows:
                        if out[rr][cc] != 5:
                            out[rr][cc] = seed[(rr - seed_rows[0]) % len(seed)]
                break

    return out
